SELECT id, log_ts, level, latency_ms, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, SHIFTRIGHT(status_code, 2) AS status_code_high, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id FROM app_logs;
